package com.careernav.service;
import com.careernav.domain.ApiModels.*;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
public class SkillGraphService {
 private record Spec(String id,String label,String category,String parent,String level){}
 private final ResumeService resumeService;private final JobService jobService;
 public SkillGraphService(ResumeService resumeService,JobService jobService){this.resumeService=resumeService;this.jobService=jobService;}
 public SkillGraph graph(String role,Long resumeId){Set<String> owned=resumeId==null?Set.of():jobService.normalize(resumeService.get(resumeId).skills());List<Spec> specs=specs(role);List<SkillNode> nodes=specs.stream().map(s->new SkillNode(s.id(),s.label(),s.level(),s.category(),demand(s.id()),owned.contains(canonical(s.id())))).toList();List<SkillLink> links=specs.stream().filter(s->s.parent()!=null).map(s->new SkillLink(s.parent(),s.id())).toList();Map<String,Integer> categories=new LinkedHashMap<>();for(SkillNode n:nodes)categories.merge(n.category(),n.demand(),Integer::sum);return new SkillGraph(role==null||role.isBlank()?"Java 后端开发":role,nodes,links,categories);}
 /** 图谱节点 id 与 normalizeSkill 的规范名对齐（带空格）。 */
 private String canonical(String id){return switch(id){case "springboot"->"spring boot";case "springcloud"->"spring cloud";case "mq"->"message queue";default->id;};}
 private int demand(String skill){long count=jobService.list("","").stream().filter(j->j.skills()!=null&&j.skills().stream().map(String::toLowerCase).anyMatch(v->v.contains(skill))).count();return(int)Math.min(100,48+count*7);}
 private List<Spec> specs(String role){String v=role==null?"":role.toLowerCase(Locale.ROOT);if(v.contains("前端")||v.contains("front"))return List.of(new Spec("web","前端工程","工程基础",null,"核心"),new Spec("html","HTML / CSS","工程基础","web","入门"),new Spec("javascript","JavaScript","语言基础","web","核心"),new Spec("typescript","TypeScript","语言基础","javascript","进阶"),new Spec("vue","Vue","主流框架","javascript","核心"),new Spec("react","React","主流框架","javascript","进阶"),new Spec("webpack","Webpack / Vite","工程化","web","进阶"),new Spec("browser","浏览器原理","性能优化","web","高阶"));if(v.contains("算法")||v.contains("ai")||v.contains("人工智能")||v.contains("大模型"))return List.of(new Spec("ai","AI 应用工程","方向核心",null,"核心"),new Spec("python","Python","语言基础","ai","入门"),new Spec("pytorch","PyTorch","模型基础","ai","核心"),new Spec("langchain","LangChain","智能体","ai","核心"),new Spec("rag","RAG 检索增强","智能体","langchain","进阶"),new Spec("mcp","MCP 工具协议","智能体","langchain","进阶"),new Spec("prompt","Prompt Engineering","应用工程","ai","入门"),new Spec("docker","Docker","工程部署","ai","进阶"));return List.of(new Spec("backend","Java 后端","方向核心",null,"核心"),new Spec("java","Java / JVM","语言基础","backend","核心"),new Spec("springboot","Spring Boot","服务框架","java","核心"),new Spec("mysql","MySQL","数据存储","backend","核心"),new Spec("redis","Redis","数据存储","backend","进阶"),new Spec("springcloud","Spring Cloud","分布式","springboot","高阶"),new Spec("mq","消息队列","分布式","springcloud","高阶"),new Spec("docker","Docker / CI/CD","工程部署","backend","进阶"));}
}
